    line = sys.stdin.readline()
    if not line:
        break
    line = line.strip()
    if line == 'isready':
        print('readyok', flush=True)
    elif line.startswith('position'):
        # Determine side to move from FEN in command
        # The last FEN field before moves list has side to move char
        m = re.search(r' ([wb]) ', line)
        if m:
            turn = m.group(1)
        else:
            turn = 'w'
    elif line.startswith('go'):
        if turn == 'b':
            val = 10000  # big score for side to move black => white is losing
        else:
            val = -10000  # white to move => white losing
        print(f'info depth 1 score cp {val}', flush=True)
        print('bestmove 0000', flush=True)
    elif line == 'quit':
        break
